UPDATE run_node
   SET execution_resolution_status = #{resolution},
       physical_completed_at = CASE WHEN #{resolution} = 'completed' THEN now() ELSE NULL END,
       physical_evidence_level = CASE WHEN #{resolution} = 'completed' THEN #{physicalEvidenceLevel} ELSE NULL END,
       physical_evidence = CASE WHEN #{resolution} = 'completed' THEN #{physicalEvidence}::jsonb ELSE '{}'::jsonb END,
       updated_at = now()
 WHERE tenant_id = #{t}
   AND run_id = #{runId}
   AND node_key = #{nodeKey}
   AND loop_index = 0

mapper.select:
SELECT count(*) FROM plate_material_effect
 WHERE tenant_id = #{t}
   AND source_run_id = #{runId}
   AND status IN ('PENDING','FAILED','REJECTED','NEEDS_RECONCILIATION')

SELECT state_version FROM plate
 WHERE tenant_id = #{t} AND id = #{plateId}
 LIMIT 1

SELECT id FROM plate_material_effect
 WHERE tenant_id = #{t} AND plate_id = #{plateId}
   AND status = 'PENDING'
   AND expected_state_version <> #{newVersion}

SELECT id, source_run_id AS "runId", source_node_key AS "nodeKey",
       source_loop_index AS "loopIndex", plate_id AS "plateId", status,
       expected_process_state AS "processState", expected_seal_state AS "sealState",
       last_error_code AS "lastErrorCode", updated_at AS "updatedAt"
  FROM plate_material_effect
 WHERE tenant_id = #{t}
 AND status = #{status} 
 AND source_run_id = #{runId} 
 AND plate_id = #{plateId} 
 ORDER BY id DESC LIMIT 200

SELECT id FROM plate_material_effect
 WHERE tenant_id = #{t}
   AND source_run_id = #{runId}
   AND source_node_key = #{nodeKey}
   AND source_loop_index = #{loopIndex}
   AND effect_index = #{effectIndex}
 LIMIT 1

