UPDATE plate_material_effect
   SET status = #{toStatus},
       last_error_code = #{lastErrorCode},
       last_error_message = #{lastErrorMessage},
       applied_at = CASE WHEN #{toStatus} = 'APPLIED' THEN now() ELSE applied_at END,
       updated_at = now()
 WHERE tenant_id = #{t}
   AND id = #{effectId}
   AND status = #{fromStatus}
